INSERT INTO public.categories (id, name, subtitle, description, image_url, badge, display_order)
VALUES 
('panetteria', 'Panetteria & Focacce', 'La bontà della tradizione', 'Lievito madre vivo, farine 100% italiane macinate a pietra e lunghissima fermentazione naturale.', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=1000&q=80', 'Fresco ogni mattina', 1),
('pasticceria', 'Pasticceria Artigianale', 'Piccoli momenti di felicità', 'Brioche sfogliate al burro di centrifuga, crostate rustiche, biscotti da tè e l’autentico maritozzo romano.', 'https://images.unsplash.com/photo-1555507036-ab1f4038808a?auto=format&fit=crop&w=1000&q=80', 'Fatto a mano', 2),
('torte-ordinazione', 'Torte su Ordinazione', 'Speciali come le tue occasioni', 'Millefoglie croccanti, torte da cerimonia, creazioni personalizzate per compleanni e anniversari.', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1000&q=80', 'Personalizzabile', 3),
('specialita-stagionali', 'Specialità Stagionali', 'Tutto da scoprire', 'I dolci delle feste romane e italiane: panettoni, colombe, frappe, castagnole e creazioni a tiratura limitata.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1000&q=80', 'Edizione Limitata', 4)
INSERT INTO public.products (id, slug, name, category, sub_category, description, ingredients, allergens, price, unit, weight, image_url, is_available, is_featured, is_weekly_special, is_seasonal, daily_quota, badge)
VALUES
('prod-pane-casereccio', 'pane-casereccio-lariano', 'Pane Casereccio di Lariano a Lievito Madre', 'panetteria', 'Pane', 'Pagnotta rustica con crosta scura e croccante, mollica alveolata e profumata. Cotto su pietra dopo 36 ore di lievitazione naturale con il nostro lievito madre centenario.', 'Farina di grano tenero tipo 1, farina integrale macinata a pietra, acqua minerale, lievito madre naturale vivo, sale marino integrale di Cervia.', '["glutine"]'::jsonb, 4.20, 'Pagnotta da 800g', '800g', 'https://images.unsplash.com/photo-1589367920969-ab8e050bbb04?auto=format&fit=crop&w=800&q=80', true, true, false, false, 50, 'Bestseller'),
('prod-pizza-bianca-romana', 'pizza-bianca-romana-pala', 'Pizza Bianca Romana alla Pala', 'panetteria', 'Pizze e Focacce', 'La vera pizza bianca della tradizione capitolina: fondo scrocchiarello, superficie dorata con bolle soffici, cosparsa di olio extravergine di oliva della Sabina DOP e fiocchi di sale.', 'Farina tipo 0 ad alta idratazione (80%), acqua fredda, lievito madre, olio extravergine d’oliva Sabina DOP, malto d’orzo, fior di sale.', '["glutine"]'::jsonb, 3.50, 'Trancio da 400g', '400g', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?auto=format&fit=crop&w=800&q=80', true, true, true, false, 40, 'Tradizione Romana'),
('prod-maritozzo-romano-classico', 'maritozzo-romano-panna-fresca', 'Maritozzo Tradizionale con Panna Montata', 'pasticceria', 'Dolci della tradizione', 'Il re della colazione romana: panino dolce soffice e profumato con sentori di vaniglia e scorza d’arancia, spaccato al centro e farcito sul momento con abbondante panna fresca montata al naturale.', 'Farina di grano tenero, uova fresche di galline allevate all’aperto, latte intero, burro di centrifuga, zucchero semolato, scorza d’arancia non trattata, lievito, panna fresca pastorizzata.', '["glutine", "latte", "uova"]'::jsonb, 3.20, 'Al pezzo', '140g', 'https://images.unsplash.com/photo-1555507036-ab1f4038808a?auto=format&fit=crop&w=800&q=80', true, true, true, false, 60, 'Specialità di Roma'),
('prod-crostata-visciole', 'crostata-visciole-selvatiche', 'Crostata Romana con Visciole Selvatiche', 'pasticceria', 'Crostate e Torte rustiche', 'Frolla burrosa e friabile preparata secondo la ricetta delle nonne romane, farcita con marmellata artigianale di visciole selvatiche dal gusto piacevolmente acidulo.', 'Farina di grano tenero, burro di fattoria, zucchero a velo, tuorli d’uovo freschi, confettura extra di visciole, vaniglia Bourbon, scorza di limone bio.', '["glutine", "latte", "uova"]'::jsonb, 18.00, 'Torta intera (diametro 22cm)', '800g', 'https://images.unsplash.com/photo-1519869325930-281384150729?auto=format&fit=crop&w=800&q=80', true, true, false, false, 15, 'Artigianale'),
('prod-torta-millefoglie-chantilly', 'torta-millefoglie-chantilly-fragoline', 'Torta Millefoglie con Chantilly e Fragoline di Nemi', 'torte-ordinazione', 'Torte da festa', 'Tre strati di sfoglia caramellata tirata a mano al burro, intervallati da vellutata crema diplomatica alla vaniglia Bourbon e profumate fragoline di bosco fresche di Nemi.', 'Pasta sfoglia artigianale, latte, tuorli, zucchero, panna fresca montata, bacca di vaniglia, fragoline di bosco, zucchero a velo.', '["glutine", "latte", "uova"]'::jsonb, 36.00, 'Formato da 1.2 kg (8-10 persone)', '1.2 kg', 'https://images.unsplash.com/photo-1535141192574-5d4897c13136?auto=format&fit=crop&w=800&q=80', true, true, false, false, 8, 'La più richiesta')
